 * Quiz logic: validate selections and score answers on submit.
 *
 * Correct answers:
 *  Q1: compiled (C), interpreted (JavaScript), both (Python)
 *  Q2: static typing (Java, TypeScript)
 *  Q3: originally designed for web front-end (JavaScript)
 */

const CORRECT = {
  q1: ["q1-c", "q1-js", "q1-python"],   // Select all that apply — C, JavaScript, Python
  q2: ["q2-java", "q2-ts"],             // Java, TypeScript
  q3: ["q3-js"],                        // JavaScript
};

const form = document.getElementById("quiz-form");
const resultEl = document.getElementById("quiz-result");

form.addEventListener("submit", (e) => {
  e.preventDefault();
  clearErrors();

  const invalid = [];

  // Validate each group has at least one selection
  Object.keys(CORRECT).forEach((groupName) => {
    const fieldset = document.getElementById(`fieldset-${groupName}`);
    const checked = form.querySelectorAll(`input[name="${groupName}"]:checked`);
    const errorEl = document.getElementById(`${groupName}-error`);

    if (checked.length === 0) {
      fieldset.dataset.invalid = "true";
      errorEl.removeAttribute("hidden");
      invalid.push(fieldset);
    }
  });

  if (invalid.length > 0) {
    // Focus first invalid fieldset's first checkbox
    const firstCheckbox = invalid[0].querySelector("input[type='checkbox']");
    firstCheckbox?.focus();

    showResult(null); // hide result if re-submitting
    return;
  }

  // Score
  let totalCorrect = 0;
  const breakdown = [];

  Object.entries(CORRECT).forEach(([groupName, correctIds]) => {
    const checked = Array.from(
      form.querySelectorAll(`input[name="${groupName}"]:checked`)
    ).map((cb) => cb.id);

    const isCorrect =
      checked.length === correctIds.length &&
      correctIds.every((id) => checked.includes(id));

    if (isCorrect) totalCorrect++;
    breakdown.push(isCorrect);
  });

  showResult(totalCorrect, breakdown);
});

function clearErrors() {
  document.querySelectorAll("fieldset[data-invalid]").forEach((fs) => {
    delete fs.dataset.invalid;
  });
  document.querySelectorAll(".error-text").forEach((el) => {
    el.setAttribute("hidden", "");
  });
}

function showResult(totalCorrect, breakdown) {
  if (totalCorrect === null) {
    resultEl.setAttribute("hidden", "");
    return;
  }

  const total = Object.keys(CORRECT).length;
  const isAllCorrect = totalCorrect === total;

  resultEl.className = isAllCorrect ? "success" : "info";
  resultEl.removeAttribute("hidden");

  const emoji = isAllCorrect ? "🎉" : totalCorrect === 0 ? "📖" : "👍";
  const msg = isAllCorrect
    ? "Perfect score! You know your languages."
    : totalCorrect === 0
    ? "Keep studying — you'll get it!"
    : "Good effort! Review the questions you missed.";

  const qLabels = breakdown
    .map((ok, i) => `Q${i + 1}: ${ok ? "✓" : "✗"}`)
    .join("  •  ");

  resultEl.innerHTML = `
    <span class="result-score">${emoji} ${totalCorrect} / ${total} correct</span>
    <span>${qLabels}</span><br>
    <span>${msg}</span>
  `;

  resultEl.scrollIntoView({ behavior: "smooth", block: "nearest" });
  resultEl.focus();
}

// Clear group error as soon as user picks an option
document.querySelectorAll(".options input[type='checkbox']").forEach((cb) => {
  cb.addEventListener("change", () => {
    const name = cb.name;
    const fieldset = document.getElementById(`fieldset-${name}`);
    const errorEl = document.getElementById(`${name}-error`);
    const anyChecked = form.querySelectorAll(`input[name="${name}"]:checked`).length > 0;

    if (anyChecked) {
      delete fieldset.dataset.invalid;
      errorEl.setAttribute("hidden", "");
    }
  });
});
