*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page:       #0f1117;
  --bg-card:       #1a1d27;
  --bg-card-hover: #1f2335;
  --border:        #2e3250;
  --border-focus:  #6c8ef7;
  --accent:        #6c8ef7;
  --accent-hover:  #8aa5ff;
  --text-primary:  #e8eaf6;
  --text-secondary:#9499b8;
  --text-help:     #7b82a8;
  --success-bg:    #0d2a1e;
  --success-border:#22c55e;
  --success-text:  #86efac;
  --error-bg:      #2a0d0d;
  --error-border:  #ef4444;
  --error-text:    #fca5a5;
  --radius:        10px;
  --shadow:        0 4px 24px rgba(0,0,0,0.5);
}

body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  padding: 2rem 1rem 4rem;
}

/* ===== Skip link ===== */
.skip-link {
  position: absolute;
  top: -999px;
  left: 1rem;
  z-index: 9999;
  padding: 0.5rem 1rem;
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  transition: top 0.1s;
}
.skip-link:focus {
  top: 1rem;
}

/* ===== Layout ===== */
main {
  max-width: 680px;
  margin: 0 auto;
}

header {
  text-align: center;
  margin-bottom: 2.5rem;
}

h1 {
  font-size: clamp(1.6rem, 4vw, 2.2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  color: var(--text-primary);
  margin-bottom: 0.4rem;
}

.subtitle {
  color: var(--text-secondary);
  font-size: 0.95rem;
}

/* ===== Quiz form ===== */
.quiz-form {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

/* ===== form-field (question card) ===== */
.form-field {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
  transition: border-color 0.2s;
}

.form-field:focus-within {
  border-color: var(--border-focus);
}

/* ===== fieldset / legend ===== */
fieldset {
  border: none;
  padding: 0;
}

legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
  padding: 0;
  width: 100%;
}

.question-number {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  border-radius: 4px;
  padding: 0.1rem 0.45rem;
  margin-right: 0.5rem;
  vertical-align: middle;
}

/* ===== Help text ===== */
.help-text {
  font-size: 0.85rem;
  color: var(--text-help);
  margin-bottom: 1rem;
  margin-top: 0.25rem;
}

/* ===== Error text ===== */
.error-text {
  font-size: 0.85rem;
  color: var(--error-text);
  margin-top: 0.75rem;
}
.error-text[hidden] { display: none; }

/* ===== Checkbox options ===== */
.options {
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
  margin-top: 0.25rem;
}

.option-label {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  padding: 0.65rem 0.9rem;
  border: 1px solid var(--border);
  border-radius: 8px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
  user-select: none;
}

.option-label:hover {
  background: var(--bg-card-hover);
  border-color: var(--accent);
}

/* Custom checkbox */
.option-label input[type="checkbox"] {
  appearance: none;
  -webkit-appearance: none;
  width: 1.1rem;
  height: 1.1rem;
  min-width: 1.1rem;
  border: 2px solid var(--text-secondary);
  border-radius: 4px;
  background: transparent;
  cursor: pointer;
  position: relative;
  transition: border-color 0.15s, background 0.15s;
}

.option-label input[type="checkbox"]:checked {
  background: var(--accent);
  border-color: var(--accent);
}

.option-label input[type="checkbox"]:checked::after {
  content: "";
  position: absolute;
  top: 1px;
  left: 4px;
  width: 5px;
  height: 9px;
  border: 2px solid #fff;
  border-top: none;
  border-left: none;
  transform: rotate(45deg);
}

.option-label input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

.option-label:has(input:checked) {
  background: rgba(108, 142, 247, 0.1);
  border-color: var(--accent);
}

.option-label:has(input[aria-invalid="true"]) {
  border-color: var(--error-border);
}

/* fieldset invalid highlight */
fieldset[data-invalid="true"] .option-label {
  border-color: var(--error-border);
}

/* ===== Submit button ===== */
.submit-btn {
  margin-top: 0.5rem;
  padding: 0.85rem 2.5rem;
  background: var(--accent);
  color: #fff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  align-self: flex-start;
  transition: background 0.2s, transform 0.1s;
  letter-spacing: 0.01em;
}

.submit-btn:hover {
  background: var(--accent-hover);
}

.submit-btn:active {
  transform: scale(0.98);
}

.submit-btn:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 3px;
}

/* ===== Result banner ===== */
#quiz-result {
  padding: 1.25rem 1.5rem;
  border-radius: var(--radius);
  border: 1px solid transparent;
  font-size: 0.95rem;
  margin-top: 0.5rem;
}
#quiz-result[hidden] { display: none; }

#quiz-result.success {
  background: var(--success-bg);
  border-color: var(--success-border);
  color: var(--success-text);
}

#quiz-result.info {
  background: #0d1a2e;
  border-color: var(--border-focus);
  color: #a5c8ff;
}

.result-score {
  font-weight: 700;
  font-size: 1.1rem;
  display: block;
  margin-bottom: 0.25rem;
}

/* ===== Forced colors ===== */
@media (forced-colors: active) {
  .option-label input[type="checkbox"]:checked {
    forced-color-adjust: none;
    background: Highlight;
    border-color: Highlight;
  }
  .submit-btn {
    forced-color-adjust: none;
  }
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition: none !important;
  }
}

/* ===== Reflow / narrow viewports ===== */
@media (max-width: 400px) {
  .form-field {
    padding: 1rem;
  }
  .submit-btn {
    width: 100%;
    text-align: center;
  }
}
