fieldset {
  border: none;
  padding: 0;
}

legend {
  font-size: 1.05rem;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
  padding: 0;
  width: 100%;
}

.question-number {
  display: inline-block;
  background: var(--accent);
  color: #fff;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  border-radius: 4px;
  padding: 0.1rem 0.45rem;
  margin-right: 0.5rem;
  vertical-align: middle;
}

/* ===== Help text ===== */
.help-text {
  font-size: 0.85rem;
  color: var(--text-help);
  margin-bottom: 1rem;
  margin-top: 0.25rem;
}

/* ===== Error text ===== */
.error-text {
  font-size: 0.85rem;
  color: var(--error-text);
  margin-top: 0.75rem;
}
.error-text[hidden] { display: none; }

